import { normalize } from "./text-utils";

export function matchValue1(input: string, fallback = "") {
  const normalized = normalize(input);
  const pattern1 = {REGEXP};

  if (pattern1.test(normalized)) {
    return normalized.replace(pattern1, fallback);
  }

  return normalized;
}

type MatchResult2 = { matched: boolean; value: string };

export class Matcher2 {
  private readonly pattern = {REGEXP};

  test(input: string): MatchResult2 {
    const value = input.trim();
    return { matched: this.pattern.test(value), value };
  }
}

export async function validateInput3(input: string) {
  const candidate = await Promise.resolve(input.trim());
  const pattern3 = {REGEXP};
  const matched = pattern3.test(candidate);

  return {
    candidate,
    matched,
    expression: pattern3.source,
  };
}

const defaults4 = ["alpha", "beta", "gamma"];

export function filterValues4(input: readonly string[]) {
  const pattern4 = {REGEXP};
  const values = [...defaults4, ...input];

  return values
    .filter((value) => pattern4.test(value))
    .map((value) => value.trim());
}

